      // =============================================================

      let numberFitFrame = 0;

      function fitNumericElement(element) {
        if (!element || !element.isConnected || element.clientWidth <= 0) return;

        element.style.fontSize = "";
        element.style.letterSpacing = "";

        const digits = (element.textContent || "").replace(/\D/g, "").length;
        const styles = window.getComputedStyle(element);
        let size = Number.parseFloat(styles.fontSize) || 16;
        let minSize = 10;

        if (element.closest(".stat")) {
          minSize = 10;
          if (digits >= 7) size = Math.min(size, 12.5);
          else if (digits >= 5) size = Math.min(size, 14.5);
        } else if (element.closest(".wallet-chip")) {
          minSize = 10;
          if (digits >= 7) size = Math.min(size, 11.5);
          else if (digits >= 5) size = Math.min(size, 13.5);
        } else if (element.classList.contains("price-pill")) {
          minSize = 10.5;
          if (digits >= 7) size = Math.min(size, 11.5);
          else if (digits >= 5) size = Math.min(size, 12.5);
        } else {
          minSize = 10.5;
          if (digits >= 7) size = Math.min(size, 12);
          else if (digits >= 5) size = Math.min(size, 13.5);
        }

        element.style.fontSize = `${size}px`;
        if (digits >= 5) element.style.letterSpacing = "-0.055em";

        while (element.scrollWidth > element.clientWidth + 1 && size > minSize) {
          size = Math.max(minSize, size - 0.5);
          element.style.fontSize = `${size}px`;
        }
      }

      function fitNumericUI() {
        window.cancelAnimationFrame(numberFitFrame);
        numberFitFrame = window.requestAnimationFrame(() => {
          const selectors = [
            ".stat strong",
            ".wallet-chip strong",
            ".price-pill",
            "[data-preview-points]",
            "[data-preview-treats]",
            "[data-owned]"
          ].join(",");
          for (const element of root.querySelectorAll(selectors)) fitNumericElement(element);
        });
      }
      // ЦЕНЫ ТОВАРОВ: в будущем меняйте только числа в этом блоке.
