      async function grantAdminCasesOrFrame(kind) {
        if (!adminAuthenticated || !adminContent) return;
        const targetTelegramId = String(adminContent.querySelector("[data-admin-grant-target]")?.value || "").trim();
        const reason = String(adminContent.querySelector("[data-admin-grant-reason]")?.value || "Компенсация").trim();
        if (!/^\d{4,20}$/.test(targetTelegramId)) {
          renderAdminDashboard("Укажите корректный Telegram ID игрока.");
          return;
        }
        try {
          if (kind === "case") {
            const caseType = String(adminContent.querySelector("[data-admin-grant-case-type]")?.value || "small");
            const quantity = Math.max(1, Math.min(20, Math.floor(Number(adminContent.querySelector("[data-admin-grant-case-count]")?.value || 1))));
            const data = await adminApiRequest(ADMIN_CASE_GRANT_PATH, { grantKind: "case", targetTelegramId, caseType, quantity, reason });
            if (targetTelegramId === String(telegramProfile?.id || "")) await loadCaseState(true);
            renderAdminDashboard(`Выдано ${data.quantity || quantity} кейс(а): ${targetTelegramId}.`);
          } else {
            const frameId = String(adminContent.querySelector("[data-admin-grant-frame-id]")?.value || "strawberry");
            const data = await adminApiRequest(ADMIN_CASE_GRANT_PATH, { grantKind: "frame", targetTelegramId, frameId, reason });
            if (targetTelegramId === String(telegramProfile?.id || "")) await loadCaseState(true);
            renderAdminDashboard(data.alreadyOwned ? `Рамка уже была у игрока ${targetTelegramId}.` : `Рамка «${data.title || frameId}» выдана игроку ${targetTelegramId}.`);
          }
        } catch (error) {
          renderAdminDashboard(adminErrorMessage(error, "Не удалось выдать компенсацию."));
        }
      }

